#!/usr/bin/env node

/**
 * Auto-Documenter MCP Server
 * Provides automatic documentation generation with task completion hooks
 * Integrates with Claude Code for seamless documentation workflow
 */

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import {
  CallToolRequestSchema,
  ErrorCode,
  ListToolsRequestSchema,
  McpError,
} from '@modelcontextprotocol/sdk/types.js';
import fs from 'fs-extra';
import path from 'path';
import { spawn } from 'child_process';
import chokidar from 'chokidar';

// Configuration with environment variable support
const CONFIG = {
  DOCS_BASE_PATH: process.env.AUTO_DOC_DOCS_PATH || path.join(process.env.HOME || process.cwd(), 'auto-docs'),
  AGENT_CLI_PATH: process.env.AUTO_DOC_CLI_PATH || path.join(process.cwd(), 'scripts', 'auto-documenter-cli.sh'),
  CLAUDE_AGENTS_PATH: process.env.CLAUDE_AGENTS_PATH || path.join(process.env.HOME || process.cwd(), '.claude', 'agents'),
  MAX_RETRIES: parseInt(process.env.AUTO_DOC_MAX_RETRIES || '3'),
  RETRY_DELAY: parseInt(process.env.AUTO_DOC_RETRY_DELAY || '1000'),
  WATCH_PATTERNS: (process.env.AUTO_DOC_WATCH_PATTERNS || '**/*.js,**/*.ts,**/*.py,**/*.md,**/*.json').split(','),
  IGNORE_PATTERNS: (process.env.AUTO_DOC_IGNORE_PATTERNS || 'node_modules/**,.git/**,dist/**,build/**').split(',')
};

// Server instance
const server = new Server(
  {
    name: 'auto-documenter',
    version: '2.0.0',
  },
  {
    capabilities: {
      tools: {},
      resources: {},
      prompts: {},
      sampling: {}
    },
  }
);

// State management
const state = {
  fileWatcher: null,
  lastDocumentationTime: new Date(),
  activeProjects: new Map(),
  documentationQueue: [],
  isProcessing: false
};

/**
 * Utility Functions
 */

// Log function with timestamp
function log(level, message, data = null) {
  const timestamp = new Date().toISOString();
  console.error(`[${timestamp}] [${level.toUpperCase()}] ${message}`, data || '');
}

// Get project name from working directory
function getProjectName(workingDir = process.cwd()) {
  return path.basename(workingDir)
    .toLowerCase()
    .replace(/[^a-z0-9-]/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

// Extract project context from environment
function extractProjectContext(workingDir = process.cwd()) {
  const projectName = getProjectName(workingDir);
  const packageJsonPath = path.join(workingDir, 'package.json');
  const readmePath = path.join(workingDir, 'README.md');

  let context = {
    projectName,
    workingDir,
    type: 'general',
    technologies: [],
    hasPackageJson: fs.existsSync(packageJsonPath),
    hasReadme: fs.existsSync(readmePath),
    timestamp: new Date().toISOString()
  };

  // Detect project type and technologies
  if (context.hasPackageJson) {
    try {
      const packageJson = fs.readJsonSync(packageJsonPath);
      context.type = 'javascript';
      context.technologies.push('Node.js');

      if (packageJson.dependencies) {
        if (packageJson.dependencies.react) context.technologies.push('React');
        if (packageJson.dependencies.express) context.technologies.push('Express');
        if (packageJson.dependencies.typescript) context.technologies.push('TypeScript');
      }
    } catch (error) {
      log('warn', 'Failed to parse package.json', error.message);
    }
  }

  // Check for other project types
  if (fs.existsSync(path.join(workingDir, 'requirements.txt')) || 
      fs.existsSync(path.join(workingDir, 'pyproject.toml'))) {
    context.type = 'python';
    context.technologies.push('Python');
  }

  if (fs.existsSync(path.join(workingDir, 'Cargo.toml'))) {
    context.type = 'rust';
    context.technologies.push('Rust');
  }

  if (fs.existsSync(path.join(workingDir, 'go.mod'))) {
    context.type = 'go';
    context.technologies.push('Go');
  }

  return context;
}

// Execute auto-documenter CLI
function executeAutoDocumenter(projectName, action = 'document', workingDir = process.cwd()) {
  return new Promise((resolve, reject) => {
    log('info', `Executing auto-documenter for project: ${projectName}`, { action, workingDir });

    const args = [action, projectName, 'implementation'];
    const child = spawn('bash', [CONFIG.AGENT_CLI_PATH, ...args], {
      cwd: workingDir,
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...process.env, PROJECT_DIR: workingDir }
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', (data) => {
      stdout += data.toString();
    });

    child.stderr.on('data', (data) => {
      stderr += data.toString();
    });

    child.on('close', (code) => {
      if (code === 0) {
        log('info', `Auto-documenter completed successfully for ${projectName}`);
        resolve({ success: true, output: stdout, error: null });
      } else {
        log('error', `Auto-documenter failed for ${projectName}`, { code, stderr });
        reject(new Error(`Auto-documenter failed with code ${code}: ${stderr}`));
      }
    });

    child.on('error', (error) => {
      log('error', `Failed to spawn auto-documenter process`, error);
      reject(error);
    });
  });
}

// Process documentation queue
async function processDocumentationQueue() {
  if (state.isProcessing || state.documentationQueue.length === 0) {
    return;
  }

  state.isProcessing = true;
  log('info', `Processing documentation queue: ${state.documentationQueue.length} items`);

  while (state.documentationQueue.length > 0) {
    const item = state.documentationQueue.shift();

    try {
      await executeAutoDocumenter(item.projectName, item.action, item.workingDir);
      state.lastDocumentationTime = new Date();

      // Update active projects
      state.activeProjects.set(item.projectName, {
        lastDocumented: new Date(),
        workingDir: item.workingDir,
        documentationCount: (state.activeProjects.get(item.projectName)?.documentationCount || 0) + 1
      });

    } catch (error) {
      log('error', `Failed to document project ${item.projectName}`, error);
    }

    // Small delay between documentation tasks
    await new Promise(resolve => setTimeout(resolve, 500));
  }

  state.isProcessing = false;
  log('info', 'Documentation queue processing completed');
}

// Queue documentation task
function queueDocumentation(projectName, action = 'document', workingDir = process.cwd()) {
  const existingIndex = state.documentationQueue.findIndex(
    item => item.projectName === projectName && item.action === action
  );

  if (existingIndex !== -1) {
    // Update existing entry
    state.documentationQueue[existingIndex] = { projectName, action, workingDir, timestamp: new Date() };
  } else {
    // Add new entry
    state.documentationQueue.push({ projectName, action, workingDir, timestamp: new Date() });
  }

  log('info', `Queued documentation task: ${projectName} (${action})`, { queueLength: state.documentationQueue.length });

  // Process queue asynchronously
  setImmediate(() => processDocumentationQueue());
}

/**
 * MCP Tool Definitions
 */

// Tool: trigger-auto-documentation
async function triggerAutoDocumentation(args) {
  const { projectName, action = 'document', workingDir = process.cwd() } = args;

  try {
    const context = extractProjectContext(workingDir);
    const finalProjectName = projectName || context.projectName;

    log('info', 'Manual trigger for auto-documentation', { 
      projectName: finalProjectName, 
      action, 
      workingDir 
    });

    queueDocumentation(finalProjectName, action, workingDir);

    return {
      success: true,
      message: `Documentation queued for project: ${finalProjectName}`,
      context,
      queueLength: state.documentationQueue.length
    };
  } catch (error) {
    log('error', 'Failed to trigger auto-documentation', error);
    throw new McpError(ErrorCode.InternalError, `Failed to trigger documentation: ${error.message}`);
  }
}

// Tool: get-documentation-status
async function getDocumentationStatus(args) {
  const { projectName } = args;

  try {
    const status = {
      activeProjects: Array.from(state.activeProjects.entries()).map(([name, data]) => ({
        name,
        ...data
      })),
      queueLength: state.documentationQueue.length,
      isProcessing: state.isProcessing,
      lastDocumentationTime: state.lastDocumentationTime,
      queue: state.documentationQueue.map(item => ({
        projectName: item.projectName,
        action: item.action,
        timestamp: item.timestamp
      }))
    };

    if (projectName) {
      status.projectStatus = state.activeProjects.get(projectName) || null;
    }

    return status;
  } catch (error) {
    log('error', 'Failed to get documentation status', error);
    throw new McpError(ErrorCode.InternalError, `Failed to get status: ${error.message}`);
  }
}

// Tool: setup-file-watching
async function setupFileWatching(args) {
  const { workingDir = process.cwd(), enable = true } = args;

  try {
    if (state.fileWatcher) {
      await state.fileWatcher.close();
      state.fileWatcher = null;
      log('info', 'Closed existing file watcher');
    }

    if (!enable) {
      return { success: true, message: 'File watching disabled' };
    }

    log('info', 'Setting up file watcher', { workingDir });

    state.fileWatcher = chokidar.watch(CONFIG.WATCH_PATTERNS, {
      cwd: workingDir,
      ignored: CONFIG.IGNORE_PATTERNS,
      persistent: true,
      ignoreInitial: true,
      awaitWriteFinish: {
        stabilityThreshold: 500,
        pollInterval: 100
      }
    });

    const context = extractProjectContext(workingDir);

    state.fileWatcher.on('change', (filepath) => {
      log('info', `File changed: ${filepath}`, { project: context.projectName });
      queueDocumentation(context.projectName, 'update', workingDir);
    });

    state.fileWatcher.on('add', (filepath) => {
      log('info', `File added: ${filepath}`, { project: context.projectName });
      queueDocumentation(context.projectName, 'update', workingDir);
    });

    state.fileWatcher.on('unlink', (filepath) => {
      log('info', `File removed: ${filepath}`, { project: context.projectName });
      queueDocumentation(context.projectName, 'update', workingDir);
    });

    state.fileWatcher.on('error', (error) => {
      log('error', 'File watcher error', error);
    });

    return {
      success: true,
      message: `File watching enabled for project: ${context.projectName}`,
      context,
      watchedPatterns: CONFIG.WATCH_PATTERNS,
      ignoredPatterns: CONFIG.IGNORE_PATTERNS
    };
  } catch (error) {
    log('error', 'Failed to setup file watching', error);
    throw new McpError(ErrorCode.InternalError, `Failed to setup file watching: ${error.message}`);
  }
}

// Tool: simulate-agent-completion
async function simulateAgentCompletion(args) {
  const { agentName, taskDescription, workingDir = process.cwd() } = args;

  try {
    const context = extractProjectContext(workingDir);

    log('info', 'Simulating agent completion', { 
      agentName, 
      taskDescription, 
      project: context.projectName 
    });

    // Queue documentation for agent completion
    queueDocumentation(context.projectName, 'agent-completion', workingDir);

    return {
      success: true,
      message: `Agent completion documented for: ${agentName}`,
      context,
      taskDescription,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    log('error', 'Failed to simulate agent completion', error);
    throw new McpError(ErrorCode.InternalError, `Failed to simulate agent completion: ${error.message}`);
  }
}

// Tool: simulate-command-completion
async function simulateCommandCompletion(args) {
  const { command, output, workingDir = process.cwd() } = args;

  try {
    const context = extractProjectContext(workingDir);

    log('info', 'Simulating command completion', { 
      command, 
      project: context.projectName 
    });

    // Queue documentation for command completion
    queueDocumentation(context.projectName, 'command-completion', workingDir);

    return {
      success: true,
      message: `Command completion documented: ${command}`,
      context,
      command,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    log('error', 'Failed to simulate command completion', error);
    throw new McpError(ErrorCode.InternalError, `Failed to simulate command completion: ${error.message}`);
  }
}

/**
 * MCP Server Setup
 */

// List available tools
server.setRequestHandler(ListToolsRequestSchema, async () => {
  return {
    tools: [
      {
        name: 'trigger-auto-documentation',
        description: 'Manually trigger automatic documentation generation for a project',
        inputSchema: {
          type: 'object',
          properties: {
            projectName: {
              type: 'string',
              description: 'Name of the project to document (auto-detected if not provided)'
            },
            action: {
              type: 'string',
              description: 'Documentation action to perform',
              enum: ['document', 'update', 'init', 'agent-completion', 'command-completion']
            },
            workingDir: {
              type: 'string',
              description: 'Working directory path (defaults to current directory)'
            }
          }
        }
      },
      {
        name: 'get-documentation-status',
        description: 'Get current status of documentation system and projects',
        inputSchema: {
          type: 'object',
          properties: {
            projectName: {
              type: 'string',
              description: 'Specific project name to get status for (optional)'
            }
          }
        }
      },
      {
        name: 'setup-file-watching',
        description: 'Setup or disable file system watching for automatic documentation',
        inputSchema: {
          type: 'object',
          properties: {
            workingDir: {
              type: 'string',
              description: 'Directory to watch (defaults to current directory)'
            },
            enable: {
              type: 'boolean',
              description: 'Enable or disable file watching (default: true)'
            }
          }
        }
      },
      {
        name: 'simulate-agent-completion',
        description: 'Simulate an agent completion event for testing automatic documentation',
        inputSchema: {
          type: 'object',
          properties: {
            agentName: {
              type: 'string',
              description: 'Name of the agent that completed'
            },
            taskDescription: {
              type: 'string',
              description: 'Description of the completed task'
            },
            workingDir: {
              type: 'string',
              description: 'Working directory (defaults to current directory)'
            }
          },
          required: ['agentName', 'taskDescription']
        }
      },
      {
        name: 'simulate-command-completion',
        description: 'Simulate a command completion event for testing automatic documentation',
        inputSchema: {
          type: 'object',
          properties: {
            command: {
              type: 'string',
              description: 'Command that was executed'
            },
            output: {
              type: 'string',
              description: 'Command output (optional)'
            },
            workingDir: {
              type: 'string',
              description: 'Working directory (defaults to current directory)'
            }
          },
          required: ['command']
        }
      }
    ]
  };
});

// Handle tool calls
server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args } = request.params;

  try {
    switch (name) {
      case 'trigger-auto-documentation':
        return { content: [{ type: 'text', text: JSON.stringify(await triggerAutoDocumentation(args || {}), null, 2) }] };

      case 'get-documentation-status':
        return { content: [{ type: 'text', text: JSON.stringify(await getDocumentationStatus(args || {}), null, 2) }] };

      case 'setup-file-watching':
        return { content: [{ type: 'text', text: JSON.stringify(await setupFileWatching(args || {}), null, 2) }] };

      case 'simulate-agent-completion':
        return { content: [{ type: 'text', text: JSON.stringify(await simulateAgentCompletion(args || {}), null, 2) }] };

      case 'simulate-command-completion':
        return { content: [{ type: 'text', text: JSON.stringify(await simulateCommandCompletion(args || {}), null, 2) }] };

      default:
        throw new McpError(ErrorCode.MethodNotFound, `Unknown tool: ${name}`);
    }
  } catch (error) {
    if (error instanceof McpError) {
      throw error;
    }
    throw new McpError(ErrorCode.InternalError, `Tool execution failed: ${error.message}`);
  }
});

/**
 * Server Lifecycle
 */

// Cleanup function
function cleanup() {
  log('info', 'Cleaning up auto-documenter MCP server');

  if (state.fileWatcher) {
    state.fileWatcher.close();
    state.fileWatcher = null;
  }

  // Process any remaining queue items
  if (state.documentationQueue.length > 0) {
    log('info', `Processing remaining ${state.documentationQueue.length} documentation tasks`);
    processDocumentationQueue().catch(error => {
      log('error', 'Failed to process remaining documentation tasks', error);
    });
  }
}

// Handle process termination
process.on('SIGINT', cleanup);
process.on('SIGTERM', cleanup);
process.on('exit', cleanup);

/**
 * Server Startup
 */

async function main() {
  log('info', 'Starting Auto-Documenter MCP Server');
  log('info', 'Configuration', CONFIG);

  // Ensure documentation directory exists
  await fs.ensureDir(CONFIG.DOCS_BASE_PATH);
  log('info', `Documentation directory ensured: ${CONFIG.DOCS_BASE_PATH}`);

  // Setup default file watching for current directory
  try {
    await setupFileWatching({ workingDir: process.cwd(), enable: true });
  } catch (error) {
    log('warn', 'Failed to setup initial file watching', error);
  }

  // Start the server
  const transport = new StdioServerTransport();
  await server.connect(transport);

  log('info', 'Auto-Documenter MCP Server started successfully');
  log('info', 'Ready to handle automatic documentation requests');
}

// Start the server
main().catch((error) => {
  log('error', 'Failed to start Auto-Documenter MCP Server', error);
  process.exit(1);
});
